import { apiClient } from "@/lib/apiClient";

// apiv3 token-kapsamlı booking detayı + ödeme talebi detayı (?token= ile sahibe açık).
// Tarayıcıdan apiClient proxy'siyle çağrılır (X-App-Token sunucuda eklenir). Hata durumunda
// apiClient ApiError fırlatır; ApiError.status alanı (404 vb.) korunur — çağıranlar onu okur.
export async function getPaymentDetail(referenceId: string, token: string) {
  return apiClient(`/bookings/${referenceId}?token=${token}`);
}

export async function getPaymentRequestDetail(
  booking_reference_id: string,
  request_id: string,
  token: string
) {
  return apiClient(
    `/bookings/${booking_reference_id}/payment-request/${request_id}?token=${token}`
  );
}
